        wheelNodeNames: string[];
        /** Scene-graph name of the steering wheel, or empty for none. */
        steeringWheelNodeName: string;
        /** Scene-graph names of the driver's arm nodes, in the order `ARM_ANTIGRAVITY_SCALE` applies. */
        armNodeNames: string[];
